<?php

declare(strict_types=1);

/*
 * Applies this project's TYPO3 settings to typo3conf/system/settings.php.
 *
 * Only the keys listed below are managed here, everything else in the file
 * stays untouched: database credentials, the encryption key and the install
 * tool password are generated by TYPO3 on the server and must never end up in
 * the repository. The script is idempotent and runs on every deployment, so
 * changes to this file reach every environment with the next deployment.
 */

$projectRoot = dirname(__DIR__, 2);
$settingsFile = $projectRoot . '/typo3conf/system/settings.php';

if (!is_file($settingsFile)) {
    fwrite(STDERR, "[settings] $settingsFile does not exist\n");
    exit(1);
}

$settings = require $settingsFile;

if (!is_array($settings)) {
    fwrite(STDERR, "[settings] $settingsFile does not return an array\n");
    exit(1);
}

/**
 * Image processing: the hosting provides ImageMagick, but the path differs
 * between servers, so it is detected instead of hard coded.
 */
$imageProcessing = ['processor_enabled' => false];

foreach (['/usr/bin/', '/usr/local/bin/', '/opt/local/bin/'] as $path) {
    if (is_executable($path . 'convert')) {
        $imageProcessing = [
            'processor_enabled' => true,
            'processor' => 'ImageMagick',
            'processor_path' => $path,
            'processor_effects' => false,
        ];
        break;
    }
    if (is_executable($path . 'gm')) {
        $imageProcessing = [
            'processor_enabled' => true,
            'processor' => 'GraphicsMagick',
            'processor_path' => $path,
            'processor_effects' => false,
        ];
        break;
    }
}

if ($imageProcessing['processor_enabled'] === false) {
    fwrite(STDOUT, "[settings] no ImageMagick/GraphicsMagick found - image processing stays disabled\n");
}

$projectSettings = [
    'SYS' => [
        'sitename' => 'signundsinn GmbH',
        // The sites are served through a reverse proxy, so the host header
        // differs from the web server's own name and has to be allowed here.
        'trustedHostsPattern' => '(?:localhost|(?:[a-z0-9-]+\.)*eywora\.com|(?:[a-z0-9-]+\.)*signundsinn\.de)(?::\d+)?',
        // Let TYPO3 read the real client address and protocol from the
        // proxy's X-Forwarded-* headers.
        'reverseProxyIP' => '*',
        'reverseProxyHeaderMultiValue' => 'first',
    ],
    'GFX' => $imageProcessing,
    'MAIL' => [
        'defaultMailFromAddress' => 'kunde@example.com',
        'defaultMailFromName' => 'signundsinn GmbH',
    ],
];

/**
 * Recursive merge: the project values win, unknown keys of the existing file
 * are kept.
 */
$merge = static function (array $target, array $source) use (&$merge): array {
    foreach ($source as $key => $value) {
        if (is_array($value) && isset($target[$key]) && is_array($target[$key])) {
            $target[$key] = $merge($target[$key], $value);
            continue;
        }
        $target[$key] = $value;
    }

    return $target;
};

$merged = $merge($settings, $projectSettings);

if ($merged === $settings) {
    fwrite(STDOUT, "[settings] already up to date\n");
    exit(0);
}

// var_export keeps the file valid PHP; TYPO3 rewrites it in its own style as
// soon as it changes a value itself.
$export = "<?php\n\nreturn " . var_export($merged, true) . ";\n";

if (file_put_contents($settingsFile, $export) === false) {
    fwrite(STDERR, "[settings] could not write $settingsFile\n");
    exit(1);
}

fwrite(STDOUT, "[settings] project settings applied\n");
